    fn parse_transaction(&self, mut transaction: Value, mut currency: Value) -> Value {
        //
        // fetchDeposits
        //
        //     {
        //         "id": "75115912",
        //         "type": "deposit",
        //         "sub-type": "NORMAL",
        //         "request-id": "trc20usdt-a2e229a44ef2a948c874366230bb56aa73631cc0a03d177bd8b4c9d38262d7ff-200",
        //         "currency": "usdt",
        //         "chain": "trc20usdt",
        //         "tx-hash": "a2e229a44ef2a948c874366230bb56aa73631cc0a03d177bd8b4c9d38262d7ff",
        //         "amount": "2849.000000000000000000",
        //         "from-addr-tag": "",
        //         "address-id": "0",
        //         "address": "TRFTd1FxepQE6CnpwzUEMEbFaLm5bJK67s",
        //         "address-tag": "",
        //         "fee": "0",
        //         "state": "safe",
        //         "wallet-confirm": "2",
        //         "created-at": "1621843808662",
        //         "updated-at": "1621843857137"
        //     },
        //
        // fetchWithdrawals
        //
        //     {
        //         "id": "61335312",
        //         "type": "withdraw",
        //         "sub-type": "NORMAL",
        //         "currency": "usdt",
        //         "chain": "trc20usdt",
        //         "tx-hash": "30a3111f2fead74fae45c6218ca3150fc33cab2aa59cfe41526b96aae79ce4ec",
        //         "amount": "12.000000000000000000",
        //         "from-addr-tag": "",
        //         "address-id": "27321591",
        //         "address": "TRf5JacJQRsF4Nm2zu11W6maDGeiEWQu9e",
        //         "address-tag": "",
        //         "fee": "1.000000000000000000",
        //         "state": "confirmed",
        //         "created-at": "1621852316553",
        //         "updated-at": "1621852467041"
        //     }
        //
        // withdraw
        //
        //     {
        //         "status": "ok",
        //         "data": "99562054"
        //     }
        //
        let mut timestamp: Value = self.safe_integer(transaction.clone(), Value::from("created-at"), Value::Undefined);
        let mut code: Value = self.safe_currency_code(self.safe_string(transaction.clone(), Value::from("currency"), Value::Undefined), Value::Undefined);
        let mut r#type: Value = self.safe_string(transaction.clone(), Value::from("type"), Value::Undefined);
        if r#type.clone() == Value::from("withdraw") {
            r#type = Value::from("withdrawal");
        };
        let mut fee_cost: Value = self.safe_string(transaction.clone(), Value::from("fee"), Value::Undefined);
        if fee_cost.clone().is_nonnullish() {
            fee_cost = Precise::string_abs(fee_cost.clone());
        };
        let mut network_id: Value = self.safe_string(transaction.clone(), Value::from("chain"), Value::Undefined);
        let mut tx_hash: Value = self.safe_string(transaction.clone(), Value::from("tx-hash"), Value::Undefined);
        if network_id.clone() == Value::from("ETH") && tx_hash.index_of(Value::from("0x")) < Value::from(0) {
            tx_hash = Value::from("0x") + tx_hash.clone();
        };
        let mut sub_type: Value = self.safe_string(transaction.clone(), Value::from("sub-type"), Value::Undefined);
        let mut internal: Value = Value::from(sub_type.clone() == Value::from("FAST"));
        return Value::Json(normalize(&Value::Json(json!({
            "info": transaction.clone(),
            "id": self.safe_string_2(transaction.clone(), Value::from("id"), Value::from("data"), Value::Undefined),
            "txid": tx_hash.clone(),
            "timestamp": timestamp.clone(),
            "datetime": self.iso8601(timestamp.clone()),
            "network": self.network_id_to_code(network_id.clone(), Value::Undefined),
            "address": self.safe_string(transaction.clone(), Value::from("address"), Value::Undefined),
            "addressTo": Value::Undefined,
            "addressFrom": Value::Undefined,
            "tag": self.safe_string(transaction.clone(), Value::from("address-tag"), Value::Undefined),
            "tagTo": Value::Undefined,
            "tagFrom": Value::Undefined,
            "type": r#type.clone(),
            "amount": self.safe_number(transaction.clone(), Value::from("amount"), Value::Undefined),
            "currency": code.clone(),
            "status": <Self as Htx>::parse_transaction_status(self, self.safe_string(transaction.clone(), Value::from("state"), Value::Undefined)),
            "updated": self.safe_integer(transaction.clone(), Value::from("updated-at"), Value::Undefined),
            "comment": Value::Undefined,
            "internal": internal.clone(),
            "fee": Value::Json(normalize(&Value::Json(json!({
                "currency": code.clone(),
                "cost": self.parse_number(fee_cost.clone(), Value::Undefined),
                "rate": Value::Undefined
            }))).unwrap())
        }))).unwrap());
    }

    fn parse_transaction_status(&self, mut status: Value) -> Value {
        let mut statuses: Value = Value::Json(normalize(&Value::Json(json!({
            "unknown": Value::from("failed"),
            "confirming": Value::from("pending"),
            "confirmed": Value::from("ok"),
            "safe": Value::from("ok"),
            "orphan": Value::from("failed"),
            "submitted": Value::from("pending"),
            "canceled": Value::from("canceled"),
            "reexamine": Value::from("pending"),
            "reject": Value::from("failed"),
            "pass": Value::from("pending"),
            "wallet-reject": Value::from("failed"),
            "confirm-error": Value::from("failed"),
            "repealed": Value::from("failed"),
            "wallet-transfer": Value::from("pending"),
            "pre-transfer": Value::from("pending"),
            "verifying": Value::from("pending")
        }))).unwrap());
        // deposit statuses
        // withdrawal statuses
        // 'confirmed': 'ok', // present in deposit statuses
        return self.safe_string(statuses.clone(), status.clone(), status.clone());
    }

    async fn withdraw(&mut self, mut code: Value, mut amount: Value, mut address: Value, mut tag: Value, mut params: Value) -> Value {
        params = params.or_default(Value::new_object());
        (tag, params) = shift_2(self.handle_withdraw_tag_and_params(tag.clone(), params.clone()));
        self.load_markets(Value::Undefined, Value::Undefined).await;
        self.check_address(address.clone());
        let mut currency: Value = self.currency(code.clone());
        let mut request: Value = Value::Json(normalize(&Value::Json(json!({
            "address": address.clone(),
            "currency": currency.get(Value::from("id")).to_lower_case()
        }))).unwrap());
        if tag.clone().is_nonnullish() {
            request.set("addr-tag".into(), tag.clone());
        };
        // only for XRP?
        let mut network_code: Value = Value::Undefined;
        (network_code, params) = shift_2(self.handle_network_code_and_params(params.clone()));
        if network_code.clone().is_nonnullish() {
            request.set("chain".into(), <Self as Htx>::network_code_to_id(self, network_code.clone(), code.clone()));
        };
        amount = parse_float(self.currency_to_precision(code.clone(), amount.clone(), network_code.clone()));
        let mut withdraw_options: Value = self.safe_value(self.get("options".into()), Value::from("withdraw"), Value::new_object());
        if self.safe_bool(withdraw_options.clone(), Value::from("includeFee"), Value::from(false)).is_truthy() {
            let mut fee: Value = self.safe_number(params.clone(), Value::from("fee"), Value::Undefined);
            if fee.clone().is_nullish() {
                let mut currencies: Value = <Self as Htx>::fetch_currencies(self, Value::Undefined).await;
                self.set("currencies".into(), self.map_to_safe_map(self.deep_extend_2(self.get("currencies".into()), currencies.clone())));
                let mut target_network: Value = self.safe_value(currency.get(Value::from("networks")), network_code.clone(), Value::new_object());
                fee = self.safe_number(target_network.clone(), Value::from("fee"), Value::Undefined);
                if fee.clone().is_nullish() {
                    return Value::Undefined;
                };
            };
            // fee needs to be deducted from whole amount
            let mut fee_string: Value = self.currency_to_precision(code.clone(), fee.clone(), network_code.clone());
            params = self.omit(params.clone(), Value::from("fee"));
            let mut amount_string: Value = self.number_to_string(amount.clone());
            let mut amount_subtracted_string: Value = Precise::string_sub(amount_string.clone(), fee_string.clone());
            let mut amount_subtracted: Value = parse_float(amount_subtracted_string.clone());
            request.set("fee".into(), parse_float(fee_string.clone()));
            amount = parse_float(self.currency_to_precision(code.clone(), amount_subtracted.clone(), network_code.clone()));
        };
        request.set("amount".into(), amount.clone());
        let mut response: Value = self.dispatch("spotPrivatePostV1DwWithdrawApiCreate".into(), extend_2(request.clone(), params.clone()), Value::Undefined).await;
        //
        //     {
        //         "status": "ok",
        //         "data": "99562054"
        //     }
        //
        return <Self as Htx>::parse_transaction(self, response.clone(), currency.clone()).await;
    }

    fn parse_transfer(&self, mut transfer: Value, mut currency: Value) -> Value {
        //
        // transfer
        //
        //     {
        //         "data": 12345,
        //         "status": "ok"
        //     }
        //
        let mut id: Value = self.safe_string(transfer.clone(), Value::from("data"), Value::Undefined);
        let mut code: Value = self.safe_currency_code(Value::Undefined, currency.clone());
        return Value::Json(normalize(&Value::Json(json!({
            "info": transfer.clone(),
            "id": id.clone(),
            "timestamp": Value::Undefined,
            "datetime": Value::Undefined,
            "currency": code.clone(),
            "amount": Value::Undefined,
            "fromAccount": Value::Undefined,
            "toAccount": Value::Undefined,
            "status": Value::Undefined
        }))).unwrap());
    }

    async fn transfer(&mut self, mut code: Value, mut amount: Value, mut from_account: Value, mut to_account: Value, mut params: Value) -> Value {
        params = params.or_default(Value::new_object());
        self.load_markets(Value::Undefined, Value::Undefined).await;
        let mut currency: Value = self.currency(code.clone());
        let mut request: Value = Value::Json(normalize(&Value::Json(json!({
            "currency": currency.get(Value::from("id")),
            "amount": parse_float(self.currency_to_precision(code.clone(), amount.clone(), Value::Undefined))
        }))).unwrap());
        let mut sub_type: Value = Value::Undefined;
        (sub_type, params) = shift_2(self.handle_sub_type_and_params(Value::from("transfer"), Value::Undefined, params.clone(), Value::Undefined));
        let mut from_account_id: Value = self.convert_type_to_account(from_account.clone());
        let mut to_account_id: Value = self.convert_type_to_account(to_account.clone());
        let mut to_cross: Value = Value::from(to_account_id.clone() == Value::from("cross"));
        let mut from_cross: Value = Value::from(from_account_id.clone() == Value::from("cross"));
        let mut to_isolated: Value = self.in_array(to_account_id.clone(), self.get("ids".into()));
        let mut from_isolated: Value = self.in_array(from_account_id.clone(), self.get("ids".into()));
        let mut from_spot: Value = Value::from(from_account_id.clone() == Value::from("pro"));
        let mut to_spot: Value = Value::from(to_account_id.clone() == Value::from("pro"));
        if from_spot.is_truthy() && to_spot.is_truthy() {
            return Value::Undefined;
        };
        let mut from_or_to_futures_account: Value = (if from_account_id.clone() == Value::from("futures") { Value::from(from_account_id.clone() == Value::from("futures")) } else { Value::from(to_account_id.clone() == Value::from("futures")) });
        let mut response: Value = Value::Undefined;
        if from_or_to_futures_account.is_truthy() {
            let mut r#type: Value = from_account_id.clone() + Value::from("-to-") + to_account_id.clone();
            r#type = self.safe_string(params.clone(), Value::from("type"), r#type.clone());
            request.set("type".into(), r#type.clone());
            response = self.dispatch("spotPrivatePostV1FuturesTransfer".into(), extend_2(request.clone(), params.clone()), Value::Undefined).await;
        } else if from_spot.is_truthy() && to_cross.is_truthy() {
            response = self.dispatch("privatePostCrossMarginTransferIn".into(), extend_2(request.clone(), params.clone()), Value::Undefined).await;
        } else if from_cross.is_truthy() && to_spot.is_truthy() {
            response = self.dispatch("privatePostCrossMarginTransferOut".into(), extend_2(request.clone(), params.clone()), Value::Undefined).await;
        } else if from_spot.is_truthy() && to_isolated.is_truthy() {
            request.set("symbol".into(), to_account_id.clone());
            response = self.dispatch("privatePostDwTransferInMargin".into(), extend_2(request.clone(), params.clone()), Value::Undefined).await;
        } else if from_isolated.is_truthy() && to_spot.is_truthy() {
            request.set("symbol".into(), from_account_id.clone());
            response = self.dispatch("privatePostDwTransferOutMargin".into(), extend_2(request.clone(), params.clone()), Value::Undefined).await;
        } else {
            if sub_type.clone() == Value::from("linear") {
                if from_account_id.clone() == Value::from("swap") || from_account.clone() == Value::from("linear-swap") {
                    from_account_id = Value::from("linear-swap");
                } else {
                    to_account_id = Value::from("linear-swap");
                };
                // check if cross-margin or isolated
                let mut symbol: Value = self.safe_string(params.clone(), Value::from("symbol"), Value::Undefined);
                params = self.omit(params.clone(), Value::from("symbol"));
                if symbol.clone().is_nonnullish() {
                    symbol = self.market_id(symbol.clone());
                    request.set("margin-account".into(), symbol.clone());
                } else {
                    request.set("margin-account".into(), Value::from("USDT"));
                };
            };
            // cross-margin
            request.set("from".into(), if from_spot.is_truthy() { Value::from("spot") } else { from_account_id.clone() });
            request.set("to".into(), if to_spot.is_truthy() { Value::from("spot") } else { to_account_id.clone() });
            response = self.dispatch("v2PrivatePostAccountTransfer".into(), extend_2(request.clone(), params.clone()), Value::Undefined).await;
        };
        //
        //    {
        //        "code": "200",
        //        "data": "660150061",
        //        "message": "Succeed",
        //        "success": true,
        //        "print-log": true
        //    }
        //
        return <Self as Htx>::parse_transfer(self, response.clone(), currency.clone()).await;
    }

